 def n(self,i,label,group,shape='box'):self.nodes[i]={'label':label,'group':group,'shape':shape};return i
 def e(self,a,b,label=''):self.edges.append((a,b,label))
 def chain(self,*ids):
  for a,b in zip(ids,ids[1:]):self.e(a,b)
 def code(self,group=None):
  edges=self.edges if group is None else [e for e in self.edges if self.nodes[e[0]]['group']==group or self.nodes[e[1]]['group']==group]
  ids=set(self.nodes) if group is None else {i for a,b,_ in edges for i in (a,b)}|{i for i,n in self.nodes.items() if n['group']==group}
  groups=list(dict.fromkeys(n['group'] for i,n in self.nodes.items() if i in ids));out='flowchart TB\n'
  for j,g in enumerate(groups):
   out+='subgraph group'+str(j)+'["'+g+'"]\n'
   for i,n in self.nodes.items():
    if i not in ids or n['group']!=g:continue
    s=n['label'].replace('&','&amp;').replace('"','&quot;').replace('<','&lt;').replace('>','&gt;') or '#160;'
    out+=i+({'box':'["'+s+'"]','action':'(["'+s+'"])','decision':'{"'+s+'"}','bar':'@{ shape: fork }'}[n['shape']])+'\n'
   out+='end\n'
  for a,b,label in edges:out+=a+' -->'+('|"'+label+'"|' if label else '')+' '+b+'\n'
  for i in sorted(ids):
   if self.nodes[i]['shape']=='bar':out+='style '+i+' fill:#222,stroke:#222\n'
  return out

